INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$872a002e$SATQ$, $SATQ$6488c559-7e14-4a19-82cc-cd8c9a18a1e7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The present-day city of Dushanbe, Tajikistan, was for years the capital of the Tajik Autonomous Soviet Socialist Republic, one of many nominally autonomous republics within the Soviet Union. Like <span aria-hidden="true">______</span><span class="sr-only">blank</span> peer autonomous Soviet socialist republics, the Tajik Republic was established along ethnolinguistic lines: most of the republic&rsquo;s residents spoke Persian.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"52b18c5e-618e-4bb7-9eaa-d4403215bc65","content":"<p>their</p>"},{"id":"39fd1ee2-b61a-4428-861c-a4f63fd7b876","content":"<p>they&rsquo;re</p>"},{"id":"b5bf41f5-6157-45ea-b416-e4eb11e0eb0a","content":"<p>its</p>"},{"id":"276d239e-1fd0-4c99-9b8b-fe39c46f735e","content":"<p>it&rsquo;s</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["b5bf41f5-6157-45ea-b416-e4eb11e0eb0a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of possessive determiners. The singular possessive determiner "its" agrees in number with the singular subject "the Tajik Republic" and thus indicates that the other republics were its peers.</p><p>Choice A is incorrect because the plural possessive determiner "their" doesn&rsquo;t agree in number with the singular subject "the Tajik Republic." Choice B is incorrect because "they&rsquo;re" is the contraction for "they are," not a possessive determiner. Choice D is incorrect because "it&rsquo;s" is the contraction for "it is" or "it has," not a possessive determiner.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"872a002e","external_id":"6488c559-7e14-4a19-82cc-cd8c9a18a1e7","vaultid":null,"uId":"61cfa936-7b69-4961-af20-5ca0674453e9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The present-day city of Dushanbe, Tajikistan, was for years the capital of the Tajik Autonomous Soviet Socialist Republic, one of many nominally autonomous republics within the Soviet Union. Like <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> peer autonomous Soviet socialist republics, the Tajik Republic was established along ethnolinguistic lines: most of the republic&rsquo;s residents spoke Persian.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"52b18c5e-618e-4bb7-9eaa-d4403215bc65","content":"<p>their</p>"},{"id":"39fd1ee2-b61a-4428-861c-a4f63fd7b876","content":"<p>they&rsquo;re</p>"},{"id":"b5bf41f5-6157-45ea-b416-e4eb11e0eb0a","content":"<p>its</p>"},{"id":"276d239e-1fd0-4c99-9b8b-fe39c46f735e","content":"<p>it&rsquo;s</p>"}],"keys":["b5bf41f5-6157-45ea-b416-e4eb11e0eb0a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of possessive determiners. The singular possessive determiner \"its\" agrees in number with the singular subject \"the Tajik Republic\" and thus indicates that the other republics were its peers.</p><p>Choice A is incorrect because the plural possessive determiner \"their\" doesn&rsquo;t agree in number with the singular subject \"the Tajik Republic.\" Choice B is incorrect because \"they&rsquo;re\" is the contraction for \"they are,\" not a possessive determiner. Choice D is incorrect because \"it&rsquo;s\" is the contraction for \"it is\" or \"it has,\" not a possessive determiner.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$8772475b$SATQ$, $SATQ$190c6d23-964f-492f-be93-b2dcb880a09c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>For thousands of years, humans have used domesticated goats (<em>Capra hircus</em>) to clear land of unwanted vegetation. When it comes to their diets, goats are notoriously <span aria-hidden="true">______</span><span class="sr-only">blank</span> they will devour all kinds of shrubs and weeds, leaving virtually no part of any plant unconsumed.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b519b42e-c0a3-433e-bb46-7928846efd31","content":"<p>indiscriminate and</p>"},{"id":"28c9f624-e6bc-4e62-9fdc-90b0c6f61b9c","content":"<p>indiscriminate,</p>"},{"id":"6a71a589-79b8-43cf-bdf9-5642e0a7ab3b","content":"<p>indiscriminate</p>"},{"id":"3f876623-436e-4b27-bc60-7a37ba389e45","content":"<p>indiscriminate:&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["3f876623-436e-4b27-bc60-7a37ba389e45"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is punctuation use between two main clauses. In this choice, a colon is correctly used to mark the boundary between one main clause ("goats are notoriously indiscriminate") and another main clause ("they will devour all kinds of shrubs and weeds") and to introduce the following explanation of goats&rsquo; nondiscriminatory behavior when it comes to what they eat.</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Furthermore, the conjunction "and" fails to indicate that what follows is an explanation of goats&rsquo; nondiscriminatory behavior when it comes to their diets. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses ("goats&hellip;indiscriminate" and "they&hellip;weeds"). Choice C is incorrect because it results in a run-on sentence. The two main clauses ("goats&hellip;indiscriminate" and "they&hellip;weeds") are fused without punctuation and/or a conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8772475b","external_id":"190c6d23-964f-492f-be93-b2dcb880a09c","vaultid":null,"uId":"879e76b7-d2d1-4141-b86e-0dc2d041f6c7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>For thousands of years, humans have used domesticated goats (<em>Capra hircus</em>) to clear land of unwanted vegetation. When it comes to their diets, goats are notoriously <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they will devour all kinds of shrubs and weeds, leaving virtually no part of any plant unconsumed.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b519b42e-c0a3-433e-bb46-7928846efd31","content":"<p>indiscriminate and</p>"},{"id":"28c9f624-e6bc-4e62-9fdc-90b0c6f61b9c","content":"<p>indiscriminate,</p>"},{"id":"6a71a589-79b8-43cf-bdf9-5642e0a7ab3b","content":"<p>indiscriminate</p>"},{"id":"3f876623-436e-4b27-bc60-7a37ba389e45","content":"<p>indiscriminate:&nbsp;</p>"}],"keys":["3f876623-436e-4b27-bc60-7a37ba389e45"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is punctuation use between two main clauses. In this choice, a colon is correctly used to mark the boundary between one main clause (\"goats are notoriously indiscriminate\") and another main clause (\"they will devour all kinds of shrubs and weeds\") and to introduce the following explanation of goats&rsquo; nondiscriminatory behavior when it comes to what they eat.</p><p>Choice A is incorrect because when coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction. Furthermore, the conjunction \"and\" fails to indicate that what follows is an explanation of goats&rsquo; nondiscriminatory behavior when it comes to their diets. Choice B is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two main clauses (\"goats&hellip;indiscriminate\" and \"they&hellip;weeds\"). Choice C is incorrect because it results in a run-on sentence. The two main clauses (\"goats&hellip;indiscriminate\" and \"they&hellip;weeds\") are fused without punctuation and/or a conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048),
    ($SATQ$8790d061$SATQ$, $SATQ$c8a945e1-d008-4cac-a824-603075e8000d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While constructing the Limyra Bridge, ancient Roman builders relied on temporary wooden beams to support the stone and brick structure. These temporary supports, a construction system known as <span aria-hidden="true">______</span><span class="sr-only">blank</span> were removed when the bridge was completed.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"bafb5297-8659-4b6e-a2d1-6d4f0bc4c42e","content":"<p>falsework;</p>"},{"id":"eb3e3829-ffef-40c0-9649-335c81154c53","content":"<p>falsework</p>"},{"id":"68b79222-27e9-4853-8ffe-0b76a7f4c76e","content":"<p>falsework,</p>"},{"id":"ef5b045a-6b05-477b-9bce-a0f671971c82","content":"<p>falsework:</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["68b79222-27e9-4853-8ffe-0b76a7f4c76e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after "falsework" pairs with the comma after "supports" to separate the supplementary element "a construction system known as falsework" from the rest of the sentence. This supplementary element functions to clarify the term "these temporary supports," and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because a semicolon can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice B is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence. Choice D is incorrect because a colon can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8790d061","external_id":"c8a945e1-d008-4cac-a824-603075e8000d","vaultid":null,"uId":"f236d7a6-b22c-4511-820a-e145125116ca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While constructing the Limyra Bridge, ancient Roman builders relied on temporary wooden beams to support the stone and brick structure. These temporary supports, a construction system known as <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> were removed when the bridge was completed.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"bafb5297-8659-4b6e-a2d1-6d4f0bc4c42e","content":"<p>falsework;</p>"},{"id":"eb3e3829-ffef-40c0-9649-335c81154c53","content":"<p>falsework</p>"},{"id":"68b79222-27e9-4853-8ffe-0b76a7f4c76e","content":"<p>falsework,</p>"},{"id":"ef5b045a-6b05-477b-9bce-a0f671971c82","content":"<p>falsework:</p>"}],"keys":["68b79222-27e9-4853-8ffe-0b76a7f4c76e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after \"falsework\" pairs with the comma after \"supports\" to separate the supplementary element \"a construction system known as falsework\" from the rest of the sentence. This supplementary element functions to clarify the term \"these temporary supports,\" and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence.</p><p>Choice A is incorrect because a semicolon can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice B is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence. Choice D is incorrect because a colon can&rsquo;t be paired with a comma in this way to separate the supplementary element from the rest of the sentence.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$886dc9f9$SATQ$, $SATQ$d608f1d2-cacf-4645-8c8c-d4f77b5cbdeb$SATQ$::uuid, $SATQ$b766cff8-38bd-45b7-8689-f6199a55234c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>On July 23, 1854, a clipper ship called the <em>Flying Cloud</em> entered San Francisco <span aria-hidden="true">______</span><span class="sr-only">blank</span> left New York Harbor under the guidance of Captain Josiah Perkins Creesy and his wife, navigator Eleanor Creesy, a mere 89 days and 8 hours earlier, the celebrated ship set a record that would stand for 135 years.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"fe0c93f8-c3c6-4088-96ff-2d188ec60f2d","content":"<p>Bay and having</p>"},{"id":"a321b192-1be0-496f-98df-3ac5ec5b5de5","content":"<p>Bay. Having</p>"},{"id":"c077a801-a047-42c5-80ec-dd148ab851dd","content":"<p>Bay, having</p>"},{"id":"54291aba-c45c-458e-8c33-1e829daa31d2","content":"<p>Bay having</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a321b192-1be0-496f-98df-3ac5ec5b5de5"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;Bay&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;On&hellip;Bay&rdquo;) and another sentence that begins with a supplementary phrase (&ldquo;Having&hellip;years&rdquo;). Here, the supplementary phrase beginning with &ldquo;having&rdquo; modifies the subject of the second sentence, &ldquo;the celebrated ship.&rdquo; </p><p>Choice A is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two sentences. Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;On&hellip;Bay&rdquo; and &ldquo;having&hellip;years&rdquo;) are fused without punctuation and/or a conjunction. </p>$SATQ$, false, 0, $SATQ$OSP-678-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$f76e1953-9f05-4322-92c8-ce7c4983ac61$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"886dc9f9","external_id":"d608f1d2-cacf-4645-8c8c-d4f77b5cbdeb","vaultid":"b766cff8-38bd-45b7-8689-f6199a55234c","uId":"2ef17144-524e-40a2-b689-9e901115c1b5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>On July 23, 1854, a clipper ship called the <em>Flying Cloud</em> entered San Francisco <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> left New York Harbor under the guidance of Captain Josiah Perkins Creesy and his wife, navigator Eleanor Creesy, a mere 89 days and 8 hours earlier, the celebrated ship set a record that would stand for 135 years.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"fe0c93f8-c3c6-4088-96ff-2d188ec60f2d","content":"<p>Bay and having</p>"},{"id":"a321b192-1be0-496f-98df-3ac5ec5b5de5","content":"<p>Bay. Having</p>"},{"id":"c077a801-a047-42c5-80ec-dd148ab851dd","content":"<p>Bay, having</p>"},{"id":"54291aba-c45c-458e-8c33-1e829daa31d2","content":"<p>Bay having</p>"}],"keys":["a321b192-1be0-496f-98df-3ac5ec5b5de5"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;Bay&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;On&hellip;Bay&rdquo;) and another sentence that begins with a supplementary phrase (&ldquo;Having&hellip;years&rdquo;). Here, the supplementary phrase beginning with &ldquo;having&rdquo; modifies the subject of the second sentence, &ldquo;the celebrated ship.&rdquo; </p><p>Choice A is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences. Choice C is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to join two sentences. Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;On&hellip;Bay&rdquo; and &ldquo;having&hellip;years&rdquo;) are fused without punctuation and/or a conjunction. </p>","parenttemplatename":"OSP-678-SEC","parenttemplateid":"","templateclusterid":"f76e1953-9f05-4322-92c8-ce7c4983ac61","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$898f182c$SATQ$, $SATQ$e0a588a4-5e5a-48bf-916c-83bd97366237$SATQ$::uuid, $SATQ$6ab66e6f-88c1-4530-9733-2be7e5cfe768$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Richard Spikes was a prolific African American inventor known for his contributions to automotive engineering. Between 1907 and 1946, he patented many inventions, <span aria-hidden="true">______</span><span class="sr-only">blank</span> an automobile turn signal, a safety brake, and&mdash;most famously&mdash;the first automatic gearshift.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"bf627286-1cde-4414-86d2-f57868a4009d","content":"<p>included</p>"},{"id":"c1a5e500-0c57-442a-8a8f-23f1fb362e29","content":"<p>includes</p>"},{"id":"ce8ba3e1-52b2-41f9-bb87-771d65afe930","content":"<p>including</p>"},{"id":"afe85b95-6af5-4e0b-872e-a9bf7b682795","content":"<p>will include</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ce8ba3e1-52b2-41f9-bb87-771d65afe930"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the use of nonfinite verb forms within a sentence. The nonfinite present participle "including" is correctly used to form a participial phrase that supplements the main clause "he patented many inventions," listing several of Spikes&rsquo;s patented inventions.</p><p>Choice A is incorrect because the finite past tense verb "included" can&rsquo;t be used in this way to supplement the main clause "he patented many inventions." Choice B is incorrect because the finite present tense verb "includes" can&rsquo;t be used in this way to supplement the main clause "he patented many inventions." Choice D is incorrect because the finite future tense verb "will include" can&rsquo;t be used in this way to supplement the main clause "he patented many inventions."</p>$SATQ$, false, 0, $SATQ$OSP-759-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$ab3c3649-6bef-4804-8c05-0034b22cea91$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"898f182c","external_id":"e0a588a4-5e5a-48bf-916c-83bd97366237","vaultid":"6ab66e6f-88c1-4530-9733-2be7e5cfe768","uId":"90543ff0-dbee-4160-af19-ea45a9741ff0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Richard Spikes was a prolific African American inventor known for his contributions to automotive engineering. Between 1907 and 1946, he patented many inventions, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> an automobile turn signal, a safety brake, and&mdash;most famously&mdash;the first automatic gearshift.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"bf627286-1cde-4414-86d2-f57868a4009d","content":"<p>included</p>"},{"id":"c1a5e500-0c57-442a-8a8f-23f1fb362e29","content":"<p>includes</p>"},{"id":"ce8ba3e1-52b2-41f9-bb87-771d65afe930","content":"<p>including</p>"},{"id":"afe85b95-6af5-4e0b-872e-a9bf7b682795","content":"<p>will include</p>"}],"keys":["ce8ba3e1-52b2-41f9-bb87-771d65afe930"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the use of nonfinite verb forms within a sentence. The nonfinite present participle \"including\" is correctly used to form a participial phrase that supplements the main clause \"he patented many inventions,\" listing several of Spikes&rsquo;s patented inventions.</p><p>Choice A is incorrect because the finite past tense verb \"included\" can&rsquo;t be used in this way to supplement the main clause \"he patented many inventions.\" Choice B is incorrect because the finite present tense verb \"includes\" can&rsquo;t be used in this way to supplement the main clause \"he patented many inventions.\" Choice D is incorrect because the finite future tense verb \"will include\" can&rsquo;t be used in this way to supplement the main clause \"he patented many inventions.\"</p>","parenttemplatename":"OSP-759-SEC","parenttemplateid":"","templateclusterid":"ab3c3649-6bef-4804-8c05-0034b22cea91","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959351,"updateDate":1691007959351}$SATQ$::jsonb, 1691007959351, 1691007959351),
    ($SATQ$89ab0d46$SATQ$, $SATQ$25a12959-71ba-4d65-8f91-fbe366e7c6c2$SATQ$::uuid, $SATQ$3912272d-83d1-4d2a-85f8-d2ba53d258d4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>After the printing press was introduced in 1440, handwritten manuscripts from Europe&rsquo;s medieval period were often destroyed and the paper used for other purposes. In one instance, pages <span aria-hidden="true">______</span><span class="sr-only">blank</span> a collection of Norse tales dating to 1270 were discovered lining a bishop&rsquo;s miter (hat).</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7453648c-b90f-4699-85a4-e9db26bd6af5","content":"<p>from:</p>"},{"id":"71085bf6-3447-42ca-8c14-f266b9a4cb87","content":"<p>from,</p>"},{"id":"ff1c5583-b91d-49ac-ad7f-20924c21876a","content":"<p>from</p>"},{"id":"7a012dfb-e52c-45d3-88ad-df6b6849c02d","content":"<p>from&mdash;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ff1c5583-b91d-49ac-ad7f-20924c21876a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The word &ldquo;from&rdquo; introduces a prepositional phrase that modifies the noun &ldquo;pages&rdquo; and provides essential information about their origin. No additional punctuation is needed after &ldquo;from&rdquo; in this context. </p><p>Choice A is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a colon. Also, a colon can only follow an independent clause, but what comes before the blank could not stand on its own as a complete sentence. Choice B is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a comma. Choice D is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a dash. </p>$SATQ$, false, 0, $SATQ$OSP-KA-BOU-E007$SATQ$, $SATQ$$SATQ$, $SATQ$5055314c-ae99-4385-883f-842c4978f487$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"89ab0d46","external_id":"25a12959-71ba-4d65-8f91-fbe366e7c6c2","vaultid":"3912272d-83d1-4d2a-85f8-d2ba53d258d4","uId":"69523bdf-0793-46e2-afa1-af38f5f8f82c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>After the printing press was introduced in 1440, handwritten manuscripts from Europe&rsquo;s medieval period were often destroyed and the paper used for other purposes. In one instance, pages <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a collection of Norse tales dating to 1270 were discovered lining a bishop&rsquo;s miter (hat).</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7453648c-b90f-4699-85a4-e9db26bd6af5","content":"<p>from:</p>"},{"id":"71085bf6-3447-42ca-8c14-f266b9a4cb87","content":"<p>from,</p>"},{"id":"ff1c5583-b91d-49ac-ad7f-20924c21876a","content":"<p>from</p>"},{"id":"7a012dfb-e52c-45d3-88ad-df6b6849c02d","content":"<p>from&mdash;</p>"}],"keys":["ff1c5583-b91d-49ac-ad7f-20924c21876a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The word &ldquo;from&rdquo; introduces a prepositional phrase that modifies the noun &ldquo;pages&rdquo; and provides essential information about their origin. No additional punctuation is needed after &ldquo;from&rdquo; in this context. </p><p>Choice A is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a colon. Also, a colon can only follow an independent clause, but what comes before the blank could not stand on its own as a complete sentence. Choice B is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a comma. Choice D is incorrect. This choice results in a punctuation error, illogically separating the preposition &ldquo;from&rdquo; from the rest of the prepositional phrase with a dash. </p>","parenttemplatename":"OSP-KA-BOU-E007","parenttemplateid":"","templateclusterid":"5055314c-ae99-4385-883f-842c4978f487","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$89fbc3eb$SATQ$, $SATQ$df9bd545-dece-46fb-bf5b-f60931397f9c$SATQ$::uuid, $SATQ$1c8e9791-08dd-44a5-8e00-0194ba309275$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The Mission 66 initiative, which was approved by Congress in 1956, represented a major investment in the infrastructure of overburdened national <span aria-hidden="true">______</span><span class="sr-only">blank</span> it prioritized physical improvements to the parks&rsquo; roads, utilities, employee housing, and visitor facilities while also establishing educational programming for the public.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"57720961-b3cc-4275-82f6-fe2a29b300da","content":"<p>parks and</p>"},{"id":"7c2a1eb8-95bc-436a-98a0-5d0690d2575b","content":"<p>parks</p>"},{"id":"c3b70aa9-0126-46a6-8e35-12e8ce30aaf1","content":"<p>parks;</p>"},{"id":"07957802-edb9-460e-9b3a-3a9e43169f5f","content":"<p>parks,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c3b70aa9-0126-46a6-8e35-12e8ce30aaf1"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon to correctly join the first main clause (&ldquo;The Mission&hellip;parks&rdquo;) and the second main clause that begins with &ldquo;it.&rdquo; </p><p>Choice A is incorrect. When coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction.&nbsp;Choice B is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.&nbsp;Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. </p>$SATQ$, false, 0, $SATQ$OSP-672-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$dc5aaa47-31d9-4537-b07a-022a4525d6f1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"89fbc3eb","external_id":"df9bd545-dece-46fb-bf5b-f60931397f9c","vaultid":"1c8e9791-08dd-44a5-8e00-0194ba309275","uId":"01d91d3b-341d-48d6-a27f-ed1a7dca7d1c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The Mission 66 initiative, which was approved by Congress in 1956, represented a major investment in the infrastructure of overburdened national <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> it prioritized physical improvements to the parks&rsquo; roads, utilities, employee housing, and visitor facilities while also establishing educational programming for the public.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"57720961-b3cc-4275-82f6-fe2a29b300da","content":"<p>parks and</p>"},{"id":"7c2a1eb8-95bc-436a-98a0-5d0690d2575b","content":"<p>parks</p>"},{"id":"c3b70aa9-0126-46a6-8e35-12e8ce30aaf1","content":"<p>parks;</p>"},{"id":"07957802-edb9-460e-9b3a-3a9e43169f5f","content":"<p>parks,</p>"}],"keys":["c3b70aa9-0126-46a6-8e35-12e8ce30aaf1"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon to correctly join the first main clause (&ldquo;The Mission&hellip;parks&rdquo;) and the second main clause that begins with &ldquo;it.&rdquo; </p><p>Choice A is incorrect. When coordinating two longer main clauses such as these, it&rsquo;s conventional to use a comma before the coordinating conjunction.&nbsp;Choice B is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction.&nbsp;Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can&rsquo;t be used in this way to join two main clauses. </p>","parenttemplatename":"OSP-672-SEC","parenttemplateid":"","templateclusterid":"dc5aaa47-31d9-4537-b07a-022a4525d6f1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$8a264a54$SATQ$, $SATQ$a760f97a-cad4-405b-85a2-3ddd2319a971$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>With a blend of traditional design elements, such as arched Gothic ceilings, and modern ones, such as floor-to-ceiling <span aria-hidden="true">______</span><span class="sr-only">blank</span> design splits the difference between old and new, a mixture that is increasingly seen in home interiors in the US.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"7fa3a196-246e-4c08-a50b-2039ec668b21","content":"<p>windows<span data-ssml-say-as=\"characters\">;</span> transitional</p>"},{"id":"18e63d12-e3c6-4a5c-8bd7-4efbdca4dc76","content":"<p>windows<span data-ssml-say-as=\"characters\">&mdash;</span>transitional</p>"},{"id":"871d44a6-1cd6-493b-a19b-a26b67a34ef8","content":"<p>windows<span data-ssml-say-as=\"characters\">.</span> Transitional</p>"},{"id":"7e6e11be-43ef-4cf8-9f3d-cadf89fb694c","content":"<p>windows<span data-ssml-say-as=\"characters\">,</span> transitional</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["7e6e11be-43ef-4cf8-9f3d-cadf89fb694c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to mark the boundary between the introductory subordinate clause ("With&hellip;windows") and the main clause ("transitional design splits the difference between old and new").</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to separate the subordinate clause ("With&hellip;windows") from the main clause ("transitional&hellip;new"). Choice B is incorrect because a dash can&rsquo;t be used in this way to separate the subordinate clause ("With&hellip;windows") from the main clause ("transitional&hellip;new"). Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with "with."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8a264a54","external_id":"a760f97a-cad4-405b-85a2-3ddd2319a971","vaultid":null,"uId":"f252e9ff-1e0d-430f-8f3a-e979948d6531","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>With a blend of traditional design elements, such as arched Gothic ceilings, and modern ones, such as floor-to-ceiling <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> design splits the difference between old and new, a mixture that is increasingly seen in home interiors in the US.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"7fa3a196-246e-4c08-a50b-2039ec668b21","content":"<p>windows<span data-ssml-say-as=\"characters\">;</span> transitional</p>"},{"id":"18e63d12-e3c6-4a5c-8bd7-4efbdca4dc76","content":"<p>windows<span data-ssml-say-as=\"characters\">&mdash;</span>transitional</p>"},{"id":"871d44a6-1cd6-493b-a19b-a26b67a34ef8","content":"<p>windows<span data-ssml-say-as=\"characters\">.</span> Transitional</p>"},{"id":"7e6e11be-43ef-4cf8-9f3d-cadf89fb694c","content":"<p>windows<span data-ssml-say-as=\"characters\">,</span> transitional</p>"}],"keys":["7e6e11be-43ef-4cf8-9f3d-cadf89fb694c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to mark the boundary between the introductory subordinate clause (\"With&hellip;windows\") and the main clause (\"transitional design splits the difference between old and new\").</p><p>Choice A is incorrect because a semicolon can&rsquo;t be used in this way to separate the subordinate clause (\"With&hellip;windows\") from the main clause (\"transitional&hellip;new\"). Choice B is incorrect because a dash can&rsquo;t be used in this way to separate the subordinate clause (\"With&hellip;windows\") from the main clause (\"transitional&hellip;new\"). Choice C is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with \"with.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669212,"updateDate":1743430669212}$SATQ$::jsonb, 1743430669212, 1743430669212),
    ($SATQ$8a3998f1$SATQ$, $SATQ$930d8bba-a206-4152-ac1c-d542102caced$SATQ$::uuid, $SATQ$a1e55c6a-40f7-4e1c-ae77-9fc06009adee$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>After the United Kingdom began rolling out taxes equivalent to a few cents on single-use plastic grocery bags in 2011, plastic-bag consumption decreased by up to ninety <span aria-hidden="true">______</span><span class="sr-only">blank</span> taxes are subject to what economists call the &ldquo;rebound effect&rdquo;: as the change became normalized, plastic-bag use started to creep back up.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"d2c3f51f-66d2-42ef-82fc-68de4eae115e","content":"<p>percent, such</p>"},{"id":"20f74816-625a-4c90-aec7-08b4ff481737","content":"<p>percent and such</p>"},{"id":"80aafb2f-cc7a-4661-9db1-369f91ceba80","content":"<p>percent. Such</p>"},{"id":"bef85b34-0588-4aba-8bdd-b2c8bb762517","content":"<p>percent such</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["80aafb2f-cc7a-4661-9db1-369f91ceba80"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;percent&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;After&hellip;percent&rdquo;) and another (&ldquo;Such&hellip;up&rdquo;). </p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.&nbsp;Choice B is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences.&nbsp;Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;After&hellip;percent&rdquo; and &ldquo;Such&hellip;up&rdquo;) are fused without punctuation and/or a conjunction. </p>$SATQ$, false, 0, $SATQ$OSP-669-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$da9477a2-f1d3-4960-b998-3e5ca08ede34$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"8a3998f1","external_id":"930d8bba-a206-4152-ac1c-d542102caced","vaultid":"a1e55c6a-40f7-4e1c-ae77-9fc06009adee","uId":"51170c0a-d3a6-4dcc-b4d8-df89a9b76af4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>After the United Kingdom began rolling out taxes equivalent to a few cents on single-use plastic grocery bags in 2011, plastic-bag consumption decreased by up to ninety <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> taxes are subject to what economists call the &ldquo;rebound effect&rdquo;: as the change became normalized, plastic-bag use started to creep back up.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"d2c3f51f-66d2-42ef-82fc-68de4eae115e","content":"<p>percent, such</p>"},{"id":"20f74816-625a-4c90-aec7-08b4ff481737","content":"<p>percent and such</p>"},{"id":"80aafb2f-cc7a-4661-9db1-369f91ceba80","content":"<p>percent. Such</p>"},{"id":"bef85b34-0588-4aba-8bdd-b2c8bb762517","content":"<p>percent such</p>"}],"keys":["80aafb2f-cc7a-4661-9db1-369f91ceba80"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after &ldquo;percent&rdquo; is used correctly to mark the boundary between one sentence (&ldquo;After&hellip;percent&rdquo;) and another (&ldquo;Such&hellip;up&rdquo;). </p><p>Choice A is incorrect because it results in a comma splice. A comma can&rsquo;t be used in this way to mark the boundary between sentences.&nbsp;Choice B is incorrect. Without a comma preceding it, the conjunction &ldquo;and&rdquo; can&rsquo;t be used in this way to join sentences.&nbsp;Choice D is incorrect because it results in a run-on sentence. The sentences (&ldquo;After&hellip;percent&rdquo; and &ldquo;Such&hellip;up&rdquo;) are fused without punctuation and/or a conjunction. </p>","parenttemplatename":"OSP-669-SEC","parenttemplateid":"","templateclusterid":"da9477a2-f1d3-4960-b998-3e5ca08ede34","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959345,"updateDate":1691007959345}$SATQ$::jsonb, 1691007959345, 1691007959345),
    ($SATQ$8a9d2f4e$SATQ$, $SATQ$b0d3e5cc-34fc-41f9-9917-58fd11be3485$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Researchers studying the &ldquo;terra-cotta army,&rdquo; the thousands of life-size statues of warriors found interred near the tomb of Emperor Qin Shi Huang of China, were shocked to realize that the shape of each statue&rsquo;s ears, like the shape of each person&rsquo;s ears, <span aria-hidden="true">______</span><span class="sr-only">blank</span> unique.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"81e22b97-e2e8-4ff6-bdc6-d046514e0cb9","content":"<p>are</p>"},{"id":"90d8ac93-ca5b-43b0-9b67-4d3a675fedda","content":"<p>&nbsp;is</p>"},{"id":"852c4a81-22a6-44c6-b18d-6aea07026f89","content":"<p>were</p>"},{"id":"03e726d7-22b1-4f52-98f1-a20b8de4d385","content":"<p>have been</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["90d8ac93-ca5b-43b0-9b67-4d3a675fedda"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb "is" agrees in number with the singular subject "the shape."</p><p>Choice A is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "the shape." Choice C is incorrect because the plural verb "were" doesn&rsquo;t agree in number with the singular subject "the shape." Choice D is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "the shape."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8a9d2f4e","external_id":"b0d3e5cc-34fc-41f9-9917-58fd11be3485","vaultid":null,"uId":"dd62e132-058d-4a47-8173-004288cd1d8b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Researchers studying the &ldquo;terra-cotta army,&rdquo; the thousands of life-size statues of warriors found interred near the tomb of Emperor Qin Shi Huang of China, were shocked to realize that the shape of each statue&rsquo;s ears, like the shape of each person&rsquo;s ears, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> unique.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"81e22b97-e2e8-4ff6-bdc6-d046514e0cb9","content":"<p>are</p>"},{"id":"90d8ac93-ca5b-43b0-9b67-4d3a675fedda","content":"<p>&nbsp;is</p>"},{"id":"852c4a81-22a6-44c6-b18d-6aea07026f89","content":"<p>were</p>"},{"id":"03e726d7-22b1-4f52-98f1-a20b8de4d385","content":"<p>have been</p>"}],"keys":["90d8ac93-ca5b-43b0-9b67-4d3a675fedda"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb \"is\" agrees in number with the singular subject \"the shape.\"</p><p>Choice A is incorrect because the plural verb \"are\" doesn&rsquo;t agree in number with the singular subject \"the shape.\" Choice C is incorrect because the plural verb \"were\" doesn&rsquo;t agree in number with the singular subject \"the shape.\" Choice D is incorrect because the plural verb \"have been\" doesn&rsquo;t agree in number with the singular subject \"the shape.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959346,"updateDate":1691007959346}$SATQ$::jsonb, 1691007959346, 1691007959346),
    ($SATQ$8b002b08$SATQ$, $SATQ$61928868-9dde-4af3-bee1-100f4eef0524$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Many Samoans enjoy a sport called kilikiti. This bat-and-ball game was derived from <span aria-hidden="true">______</span><span class="sr-only">blank</span> kilikiti differs from cricket in a few key ways.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"96ec98d1-244a-4aed-8eaf-e92a5519be67","content":"<p>cricket but:</p>"},{"id":"26bbe65c-523a-4712-a819-b2aa261fac85","content":"<p>cricket but,</p>"},{"id":"946b5fc9-1fe0-4edf-84e0-a7a8d715a5c5","content":"<p>cricket, but</p>"},{"id":"fb0849e7-6e45-4c95-8cc8-048181ae97bd","content":"<p>cricket, but,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["946b5fc9-1fe0-4edf-84e0-a7a8d715a5c5"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma before the coordinating conjunction "but" to join the first main clause ("This bat-and-ball game was derived from cricket") and the second main clause ("kilikiti differs from cricket in a few key ways").</p><p>Choice A is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a colon in this way after the coordinating conjunction. Choice B is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a comma in this way after the coordinating conjunction. Choice D is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a comma in this way after the coordinating conjunction.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8b002b08","external_id":"61928868-9dde-4af3-bee1-100f4eef0524","vaultid":null,"uId":"4b29665b-7b7b-470e-971c-04d794dd0089","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Many Samoans enjoy a sport called kilikiti. This bat-and-ball game was derived from <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> kilikiti differs from cricket in a few key ways.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"96ec98d1-244a-4aed-8eaf-e92a5519be67","content":"<p>cricket but:</p>"},{"id":"26bbe65c-523a-4712-a819-b2aa261fac85","content":"<p>cricket but,</p>"},{"id":"946b5fc9-1fe0-4edf-84e0-a7a8d715a5c5","content":"<p>cricket, but</p>"},{"id":"fb0849e7-6e45-4c95-8cc8-048181ae97bd","content":"<p>cricket, but,</p>"}],"keys":["946b5fc9-1fe0-4edf-84e0-a7a8d715a5c5"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma before the coordinating conjunction \"but\" to join the first main clause (\"This bat-and-ball game was derived from cricket\") and the second main clause (\"kilikiti differs from cricket in a few key ways\").</p><p>Choice A is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a colon in this way after the coordinating conjunction. Choice B is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a comma in this way after the coordinating conjunction. Choice D is incorrect. When coordinating two main clauses such as these, it&rsquo;s not conventional to use a comma in this way after the coordinating conjunction.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323049,"updateDate":1730147323049}$SATQ$::jsonb, 1730147323049, 1730147323049),
    ($SATQ$8b017d4e$SATQ$, $SATQ$ada8e0c6-49b4-4d07-9331-b165a187a3f9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Supported by biochemical analyses of over 2,000 skeletons from the Middle Ages, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"4febb40c-fdb3-4192-952c-65b1947accda","content":"<p>vegetables and grains were, a 2022 study found, the primary components of early medieval rulers&rsquo; diets.</p>"},{"id":"051db984-d394-4b3a-be83-ed1db6905f3b","content":"<p>early medieval rulers&rsquo; diets were found, in a 2022 study, to have primarily consisted of vegetables and grains.</p>"},{"id":"30c4ef74-af45-4627-b4ae-00b54c0148a8","content":"<p>the primary components of early medieval rulers&rsquo; diets were vegetables and grains, according to a 2022 study.</p>"},{"id":"3b7bde41-44a7-4dc3-8a85-167a24a0ea06","content":"<p>findings from a 2022 study suggested that vegetables and grains were the primary components of early medieval rulers&rsquo; diets.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["3b7bde41-44a7-4dc3-8a85-167a24a0ea06"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase "findings from a 2022 study" the subject of the sentence and places it immediately after the modifying phrase "supported...Ages." In doing so, this choice clearly establishes that the findings&mdash;and not another noun in the sentence&mdash;are supported by the biochemical analyses.</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of "vegetables and grains" immediately after the modifying phrase illogically suggests that vegetables and grains are supported by biochemical analyses. Choice B is incorrect because it results in a dangling modifier. The placement of "early medieval rulers&rsquo; diets" immediately after the modifying phrase illogically suggests that the rulers&rsquo; diets are supported by biochemical analyses. Choice C is incorrect because it results in a dangling modifier. The placement of "the primary components" immediately after the modifying phrase illogically suggests that the primary components are supported by biochemical analyses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"8b017d4e","external_id":"ada8e0c6-49b4-4d07-9331-b165a187a3f9","vaultid":null,"uId":"127352f5-9d2b-48b0-af07-860f1b0c6db0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Supported by biochemical analyses of over 2,000 skeletons from the Middle Ages, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"4febb40c-fdb3-4192-952c-65b1947accda","content":"<p>vegetables and grains were, a 2022 study found, the primary components of early medieval rulers&rsquo; diets.</p>"},{"id":"051db984-d394-4b3a-be83-ed1db6905f3b","content":"<p>early medieval rulers&rsquo; diets were found, in a 2022 study, to have primarily consisted of vegetables and grains.</p>"},{"id":"30c4ef74-af45-4627-b4ae-00b54c0148a8","content":"<p>the primary components of early medieval rulers&rsquo; diets were vegetables and grains, according to a 2022 study.</p>"},{"id":"3b7bde41-44a7-4dc3-8a85-167a24a0ea06","content":"<p>findings from a 2022 study suggested that vegetables and grains were the primary components of early medieval rulers&rsquo; diets.</p>"}],"keys":["3b7bde41-44a7-4dc3-8a85-167a24a0ea06"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase \"findings from a 2022 study\" the subject of the sentence and places it immediately after the modifying phrase \"supported...Ages.\" In doing so, this choice clearly establishes that the findings&mdash;and not another noun in the sentence&mdash;are supported by the biochemical analyses.</p><p>Choice A is incorrect because it results in a dangling modifier. The placement of \"vegetables and grains\" immediately after the modifying phrase illogically suggests that vegetables and grains are supported by biochemical analyses. Choice B is incorrect because it results in a dangling modifier. The placement of \"early medieval rulers&rsquo; diets\" immediately after the modifying phrase illogically suggests that the rulers&rsquo; diets are supported by biochemical analyses. Choice C is incorrect because it results in a dangling modifier. The placement of \"the primary components\" immediately after the modifying phrase illogically suggests that the primary components are supported by biochemical analyses.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$8d53e7a0$SATQ$, $SATQ$580a6b24-5b50-42e6-a22d-aa65afc91c80$SATQ$::uuid, $SATQ$044835fc-4ed8-4f7a-af7e-a74b8a26a013$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Slam poet Elizabeth Acevedo&rsquo;s debut novel <em>The Poet X</em>,<em> </em>winner of the 2018 National Book Award for Young People&rsquo;s Literature, is composed of <span aria-hidden="true">______</span><span class="sr-only">blank</span> protagonist, fifteen-year-old Xiomara Batista.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"9bd53fe8-e5c9-474b-a179-8e6aaec95bf2","content":"<p>poems putatively written by the novel&rsquo;s</p>"},{"id":"92794068-2df8-4071-96cd-b62a0593ef69","content":"<p>poem&rsquo;s putatively written by the novel&rsquo;s&nbsp;</p>"},{"id":"eecd108a-f8b3-4b06-801a-e9a805491d41","content":"<p>poem&rsquo;s putatively written by the novels&rsquo;</p>"},{"id":"0f55a76d-7cd5-497a-966f-24b928f800ba","content":"<p>poems putatively written by the novels&rsquo;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["9bd53fe8-e5c9-474b-a179-8e6aaec95bf2"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Nothing belongs to the &ldquo;poems&rdquo; in the sentence, so it should not be possessive&mdash;just a simple plural noun. The protagonist does belong to the novel&mdash;it&rsquo;s the protagonist of the novel&mdash;so &ldquo;novel&rdquo; needs to be a singular possessive noun. </p><p>Choice B is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This choice uses the singular possessive &ldquo;poem&rsquo;s,&rdquo; but the text indicates that it should be the simple plural &ldquo;poems&rdquo;: there is more than one poem, and nothing belongs to the poems.&nbsp;Choice C is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This choice uses the singular possessive &ldquo;poem&rsquo;s,&rdquo; but the text indicates that it should be the simple plural &ldquo;poems&rdquo;: there is more than one poem, and nothing belongs to the poems. This choice also uses the plural possessive &ldquo;novels&rsquo;,&rdquo; which is incorrect because there is only one novel.&nbsp;Choice D is incorrect. This doesn&rsquo;t complete the text in a way that conforms to the conventions of Standard English. This choice uses the plural possessive &ldquo;novels&rsquo;,&rdquo; which is incorrect because there is only one novel, so it should be the singular possessive &ldquo;novel&rsquo;s.&rdquo;&nbsp;. </p>$SATQ$, false, 0, $SATQ$OSP-634-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$9ae4cb96-e277-491b-b913-c095267f78f9$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"8d53e7a0","external_id":"580a6b24-5b50-42e6-a22d-aa65afc91c80","vaultid":"044835fc-4ed8-4f7a-af7e-a74b8a26a013","uId":"959b432d-07a1-488a-ace9-a631cf867d5f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Slam poet Elizabeth Acevedo&rsquo;s debut novel <em>The Poet X</em>,<em> </em>winner of the 2018 National Book Award for Young People&rsquo;s Literature, is composed of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> protagonist, fifteen-year-old Xiomara Batista.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"9bd53fe8-e5c9-474b-a179-8e6aaec95bf2","content":"<p>poems putatively written by the novel&rsquo;s</p>"},{"id":"92794068-2df8-4071-96cd-b62a0